'use strict';
// Explicit amendments for demonstrated crossed references and stale seed descriptions.
// No pair dialogue, card text, scene ratings, transfer wording or review status may change.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),c=require('./core.cjs');
const scopes={D119:'S118+D119',D126:'S144+D126',S111:'S111+D103',S118:'S118+D119',S144:'S144+D126',S208:'S208+D203',D02:'S19+D02',D06:'S124+D06',D14:'S22+D14'};
function scope(spec){
 assert.equal(spec.schema,2);assert.ok(Array.isArray(spec.repairs)&&spec.repairs.length>0);assert.equal(new Set(spec.repairs.map(r=>r.key)).size,spec.repairs.length);
 for(const r of spec.repairs){assert.ok(scopes[r.key],'Undemonstrated provenance scope');assert.ok(r.authorAssessment.length>=20&&/A1/.test(r.authorAssessment));assert.ok(r.changes.length>0);assert.equal(new Set(r.changes.map(x=>x.exampleId)).size,r.changes.length);for(const x of r.changes)assert.ok([scopes[r.key]+'-a',scopes[r.key]+'-b'].includes(x.exampleId),'Unrelated pair amendment');}
 assert.ok(spec.selectedIds.length>0);assert.equal(new Set(spec.selectedIds).size,spec.selectedIds.length);for(const id of spec.selectedIds)assert.ok(spec.repairs.some(r=>id===r.key+'-single-a'||id===r.key+'-single-b'),'Unrelated accepted scene');return spec;
}
function changedPairs(pairs,changes){
 const result=structuredClone(pairs);
 for(const x of changes){assert.deepEqual(Object.keys(x).sort(),['exampleId','beforeSeedUse','afterSeedUse','beforeSeedRefs','afterSeedRefs','beforeRecordHash','afterRecordHash','reason'].sort());assert.ok(x.reason.length>=20&&x.afterSeedUse.length>=20);const original=result.find(p=>p.id===x.exampleId);assert.ok(original);assert.equal(c.hash(original),x.beforeRecordHash,'Provenance before-record conflict');assert.equal(original.seedUse,x.beforeSeedUse);assert.deepEqual(original.seedRefs,x.beforeSeedRefs);assert.equal(x.afterSeedRefs.length,2);const keys=original.id.replace(/-[ab]$/,'').split('+');for(let n=0;n<2;n++)assert.ok([keys[n]+'-single-a',keys[n]+'-single-b'].includes(x.afterSeedRefs[n]),'Cross-card seed reference');original.seedUse=x.afterSeedUse;original.seedRefs=x.afterSeedRefs;assert.notEqual(c.hash(original),x.beforeRecordHash,'Empty provenance amendment');assert.equal(c.hash(original),x.afterRecordHash,'Provenance after-record conflict');}
 return result;
}
function blind(input,writer,spec){
 scope(spec);return {rubric:c.rubric,records:[],bindings:spec.repairs.map(r=>{
 const raw=input.bindings.find(b=>b.key===r.key);assert.ok(raw);const pairs=changedPairs(raw.bespokePairs,r.changes),seeds=r.supportingSeeds;
 assert.equal(new Set(seeds.map(s=>s.scene.id)).size,seeds.length);for(const s of seeds){assert.equal(c.hash(s.scene),s.sourceHash,'Supporting seed drift');assert.ok(pairs.some(p=>p.id.replace(/-[ab]$/,'').split('+').includes(s.card.id)),'Unrelated supporting card');assert.ok(s.scene.id.startsWith(s.card.id+'-single-'));}
 for(const id of new Set(pairs.flatMap(p=>p.seedRefs)))assert.ok(seeds.some(s=>s.scene.id===id),'Missing exact supporting seed');
 return {key:r.key,card:input.records.find(x=>x.key===r.key).card,transfer:raw.transfer,bespokePairs:pairs,supportingSeeds:seeds,candidateDialogues:input.records.filter(x=>x.key===r.key).map(x=>({card:x.card,exampleId:x.exampleId,beats:writer.records.find(w=>w.exampleId===x.exampleId).beats})),provenanceChanges:r.changes,scope:'Binding-only fresh review. Assess the exact amended seedRefs and seedUse against unchanged pair dialogue, exact current supporting seeds, and the accepted candidate single dialogues. Distinguish literal inherited material from conceptual adaptation. Explicit historical contrasts may refer to the supplied original single dialogue; do not treat them as claims about a revised seed. Review every transfer field unchanged. Report any remaining real incompatibility. records must be empty. Do not rerate single or pair dialogue or infer exact-pair approval. No writer scores or improvement claims supplied.'};
 })};
}
function derive(input,writer,review,spec,bindingReview){
 scope(spec);c.validateWriter(input,writer);c.validateReview(c.reviewerInput(input,writer),review);
 for(const id of spec.selectedIds)assert.ok(review.records.find(r=>r.exampleId===id)?.accept,'Unresolved selected dialogue');
 for(const r of spec.repairs)assert.ok([...writer.bindings,...review.bindings].some(b=>b.key===r.key&&!b.compatible),'No demonstrated binding hold');
 const supplied=blind(input,writer,spec);c.validateReview(supplied,bindingReview);assert.equal(bindingReview.records.length,0);assert.ok(bindingReview.bindings.every(b=>b.compatible),'Fresh binding review rejected the repair');
 const result={input:structuredClone(input),writer:structuredClone(writer),review:structuredClone(review)};
 for(const r of spec.repairs){const raw=result.input.bindings.find(b=>b.key===r.key);raw.bespokePairs=changedPairs(raw.bespokePairs,r.changes);raw.supportingSeeds=r.supportingSeeds;result.writer.bindings=result.writer.bindings.map(b=>b.key===r.key?{key:r.key,compatible:true,assessment:r.authorAssessment}:b);result.review.bindings=result.review.bindings.map(b=>b.key===r.key?bindingReview.bindings.find(x=>x.key===r.key):b);}
 assert.deepEqual(result.writer.records,writer.records);assert.deepEqual(result.review.records,review.records);c.validateWriter(result.input,result.writer);c.validateReview(c.reviewerInput(result.input,result.writer),result.review);require('./per-example.cjs').assertSelection(result.input,result.writer,result.review,spec.selectedIds);return result;
}
function amended(doc,spec){scope(spec);const result=structuredClone(doc),records=result.records||result;for(const r of spec.repairs)records[scopes[r.key]]=changedPairs(records[scopes[r.key]],r.changes);return result;}
function applySource(root,spec){const file=path.join(root,'examples/authoring/pair-scenes.json');c.save(file,amended(c.read(file),spec));}
function assertSourceChange(before,after,folder,spec){assert.deepEqual(c.read(path.join(after,'examples/authoring/pair-scenes.json')),amended(c.read(path.join(before,'examples/authoring/pair-scenes.json')),spec),'Only explicit seedRefs/seedUse amendments may change');}
function assertApplied(root,spec){scope(spec);const doc=c.read(path.join(root,'examples/authoring/pair-scenes.json')),records=doc.records||doc;for(const r of spec.repairs)for(const x of r.changes)assert.equal(c.hash(records[scopes[r.key]].find(p=>p.id===x.exampleId)),x.afterRecordHash,'Applied provenance differs from reviewed amendment');}
function referenceAmendments(beforeRoot,afterRoot,directIds,folders=[]){
 const amendments=new Map();for(const folder of typeof folders==='string'?[folders]:folders){assert.match(folder,/^editorial[\\/]local-[a-zA-Z0-9_-]+$/,'Invalid provenance evidence folder');const file=path.join(afterRoot,folder,'binding-recovery.json');if(!fs.existsSync(file))continue;const spec=c.read(file);if(spec.schema!==2)continue;
 require('./binding-recovery.cjs').verify(path.dirname(file),{specHash:c.hash(spec)});scope(spec);for(const id of spec.selectedIds)assert.ok(directIds.includes(id),'Provenance amendment outside integrated scope');const before=c.read(path.join(beforeRoot,'examples/authoring/pair-scenes.json')),after=c.read(path.join(afterRoot,'examples/authoring/pair-scenes.json'));
 for(const r of spec.repairs)for(const change of r.changes){const b=(before.records||before)[scopes[r.key]].find(p=>p.id===change.exampleId),a=(after.records||after)[scopes[r.key]].find(p=>p.id===change.exampleId);assert.equal(c.hash(b),change.beforeRecordHash);assert.equal(c.hash(a),change.afterRecordHash);assert.ok(!amendments.has(change.exampleId),'Overlapping provenance amendments require an explicit chain');amendments.set(change.exampleId,change);}}
 return amendments;
}
function assertReferenceChange(before,after,amendment){assert.ok(amendment,'Unrelated generated record changed '+after.id);assert.equal(before.id,amendment.exampleId);assert.equal(after.id,amendment.exampleId);assert.deepEqual(before.seedRefs,amendment.beforeSeedRefs);assert.deepEqual(after.seedRefs,amendment.afterSeedRefs);assert.deepEqual({...after,seedRefs:before.seedRefs},before,'Generated amendment changed more than seedRefs');}
module.exports={scopes,scope,changedPairs,blind,derive,applySource,assertSourceChange,assertApplied,referenceAmendments,assertReferenceChange};
